mapper.select:
SELECT * FROM programming_capabilities pc join student_information si on pc.student_number = si.student_number


        AND pc.student_name LIKE CONCAT('%',#{studentName},'%')


        AND pc.student_number LIKE CONCAT('%',#{studentNumber},'%')


        AND si.classes = #{classes}


        AND si.grade = #{grade}


        AND si.major = #{major}


        AND si.college = #{college}
